// src/App.js
import React from 'react'
import { Routes,Route } from 'react-router-dom';
import Landing from './pages/Landing'; // تأكد من المسار الصحيح
import Login from './pages/Login';
function App() {
  return (
   <div className="App">
    <Routes>
   <Route path="/" element={<Landing/>}/>
  <Route path="/" element={<Login/>}/>
  
    </Routes>
   </div>
  );   
  
}

export default App;
